const paths=[['js-grammar','Grammar and types','files/en-us/web/javascript/guide/grammar_and_types/index.md'],['js-functions','Functions','files/en-us/web/javascript/guide/functions/index.md'],['js-objects','Working with objects','files/en-us/web/javascript/guide/working_with_objects/index.md'],['js-collections','Indexed collections','files/en-us/web/javascript/guide/indexed_collections/index.md'],['js-modules','JavaScript modules','files/en-us/web/javascript/guide/modules/index.md'],['js-errors','Control flow and error handling','files/en-us/web/javascript/guide/control_flow_and_error_handling/index.md']];
module.exports=course('js-fundamentals',units,paths.map(([id,title,path])=>({id,title:'MDN: '+title,url:'https://github.com/mdn/content/blob/'+commit+'/'+path,source:{repo:'mdn/content',commit,path,verification:'Pinned official MDN source; original prose and actual isolated JavaScript examples.'}})));
